class Solution {
public:
    int binaryGap(int n) {
        int last_idx = -1, max_gap = 0, idx = 0;
        while (n > 0) {
            if (n & 1) {
                if (last_idx != -1) {
                    max_gap = max(max_gap, idx - last_idx);
                }
                last_idx = idx;
            }
            n >>= 1;
            idx++;
        }
        return max_gap;
    }
};

class Solution {
    public int binaryGap(int n) {
        int lastIdx = -1, maxGap = 0, idx = 0;
        while (n > 0) {
            if ((n & 1) == 1) {
                if (lastIdx != -1) {
                    maxGap = Math.max(maxGap, idx - lastIdx);
                }
                lastIdx = idx;
            }
            n >>= 1;
            idx++;
        }
        return maxGap;
    }
}

var binaryGap = function(n) {
    let lastIdx = -1, maxGap = 0, idx = 0;
    while (n > 0) {
        if (n & 1) {
            if (lastIdx !== -1) {
                maxGap = Math.max(maxGap, idx - lastIdx);
            }
            lastIdx = idx;
        }
        n >>= 1;
        idx++;
    }
    return maxGap;
};
